166	// Default script: rooms and an empty list answer at once.
167	export const ROOMS = ['Aurora', 'Borealis', 'Cosmos'];
168	export function okScript(bookings = []) {
169	  return (call) => {
170	    if (call.url === '/api/rooms') return reply(200, { rooms: ROOMS });
171	    if (!call.options || call.options.method === 'GET') return reply(200, { bookings });
172	    return undefined;
173	  };
174	}
