19	async function tmp(t) {
20	  const dir = await makeTempDir();
21	  t.after(() => removeDir(dir));
22	  return dir;
23	}
24	
25	async function boot(t, opts) {
26	  const server = await startServer(opts);
27	  t.after(() => server.stop());
28	  return server;
29	}
