31	async function holdPort(t, port = 0) {
32	  const server = net.createServer();
33	  await new Promise((resolve, reject) => {
34	    server.once('error', reject);
35	    server.listen(port, '127.0.0.1', resolve);
36	  });
37	  t.after(() => new Promise((resolve) => server.close(resolve)));
38	  return server.address().port;
39	}
