41	function assertOneLine(result, expectedCode = 1) {
42	  assert.equal(result.code, expectedCode);
43	  assert.equal(result.stdout, '');
44	  assert.ok(result.stderr.length > 1);
45	  assert.ok(result.stderr.endsWith('\n'));
46	  assert.equal(result.stderr.split('\n').length, 2);
47	}
