169	async function prepareBad(dir, entry) {
170	  if (entry.content === null) await mkdir(join(dir, entry.check));
171	  else await seed(join(dir, entry.check), entry.content);
172	}
173	
174	for (const entry of BAD_FILES) {
175	  test(`unusable data file (${entry.label}) exits 1 and leaves it untouched`, async (t) => {
176	    const dir = await tmp(t);
177	    await prepareBad(dir, entry);
178	    const before = entry.content === null ? null : await readFile(join(dir, entry.check));
179	    const result = await runToExit({ cwd: dir, env: { DATA_FILE: entry.given } });
180	    assert.deepEqual(result, { code: 1, stdout: '', stderr: `cannot read data file ${entry.given}\n` });
181	    if (before === null) assert.ok((await stat(join(dir, entry.check))).isDirectory());
182	    else assert.deepEqual(await readFile(join(dir, entry.check)), before);
183	  });
